from produire import produire,paras,steps,table
from medicaments import q

def avertissement(l):
 t=paras('Exemple documenté par la notice suisse Otrivin Rhume Classic, xylométazoline n°24926. Cette fenêtre décrit le risque iatrogène ; elle ne recommande pas une nouvelle cure pour traiter la congestion rebond.')
 t+=q('24926',"Otrivin Rhume Classic ne doit pas être utilisé pendant plus d'une semaine, une utilisation plus longue pouvant entraîner une rhinite médicamenteuse.")
 t+=q('24926',"Comme pour d'autres vasoconstricteurs locaux, un traitement continu durant plus d'une semaine par Otrivin Rhume Classic n'est pas indiqué. En effet, une rhinite médicamenteuse accompagnée de congestion de la muqueuse nasale, dont les symptômes sont très semblables à ceux d'un rhume, peut se manifester.")
 t+=paras('La limite est propre à cette information professionnelle ; elle ne constitue pas un délai minimal à atteindre ni un test diagnostique. Les doses et restrictions par forme et âge figurent dans le cours principal. Ne pas remplacer un vasoconstricteur par un autre de même mécanisme pour prolonger l’usage.')
 return l.subwindow('risque-iatrogene','Xylométazoline : avertissement suisse exact',t,(14,))
produire(3,[
('La {rhinite médicamenteuse} est une congestion nasale entretenue par l’utilisation prolongée d’un décongestionnant vasoconstricteur local. Le produit soulage brièvement puis la gêne réapparaît. Ce cycle peut conduire à augmenter les prises.',paras('Elle appartient aux causes iatrogènes de rhinite non allergique. Une rhinite causée par un autre médicament systémique relève d’une analyse distincte ; tous les sprays nasaux ne provoquent pas ce même mécanisme.')),
('Le {contexte est celui d’une automédication ou d’une prolongation de traitement}. Un rhume, une allergie ou une obstruction structurelle peut avoir motivé le premier usage. La maladie initiale peut persister en parallèle.',paras('Demander les flacons utilisés, y compris ceux achetés sans ordonnance ou sous plusieurs marques. Une utilisation conforme brève ne démontre pas une rhinite médicamenteuse ; l’histoire et l’évolution sont nécessaires. Aucun chiffre de prévalence suisse n’est attribué sans donnée vérifiée.')),
('Le {mécanisme associe effet vasculaire et congestion rebond}. L’effet bref sur la muqueuse ne traite pas forcément la cause de l’obstruction. La répétition peut entretenir le symptôme qu’elle devait soulager.',paras('La notice de xylométazoline décrit une congestion ressemblant à un rhume lors d’utilisation prolongée. Le conservateur peut aussi irriter ou gonfler la muqueuse ; cela ne permet pas de réduire toute la maladie au seul excipient.')),
('Les {signes de gravité ne sont pas attribués au seul rebond}. Céphalée brutale sévère, trouble visuel ou signe neurologique sous sympathomimétique impose une consultation immédiate. Une détresse ou une intoxication suspectée nécessite une réponse urgente.',paras('La notice décrit aussi des effets cardiovasculaires et des manifestations neurologiques en cas d’usage excessif ou d’ingestion. Chez l’enfant, somnolence inhabituelle ou trouble respiratoire après exposition n’est pas un simple nez bouché. Une masse, un saignement focal ou une obstruction post-traumatique reste à explorer.')),
('L’{anamnèse reconstitue précisément l’exposition}. Nom, principe actif, concentration, forme, fréquence et durée sont notés. Le patient doit pouvoir expliquer l’usage sans être culpabilisé.',paras('Demander ce qui se passe entre les prises, l’évolution des doses et les tentatives d’arrêt. Rechercher la cause initiale, les autres médicaments et les facteurs qui rendent l’arrêt difficile, notamment le sommeil. Ne pas confondre vasoconstricteur, solution saline et corticoïde nasal.')),
('L’{examen apprécie la muqueuse et les obstacles associés}. Congestion ou irritation peuvent être présentes sans aspect pathognomonique. Une anomalie focale ou une persistance atypique appelle un bilan adapté.',paras('Examiner cloison, cornets, sécrétions et éventuelles lésions. L’endoscopie peut être nécessaire pour une obstruction inexpliquée ou persistante. Une réponse temporaire au vasoconstricteur ne prouve pas l’absence d’une anomalie structurelle.')),
('L’{approche syndromique} relie symptôme et chronologie médicamenteuse. Elle garde ouvertes les causes concomitantes. Le diagnostic n’est pas fondé sur la seule présence d’un flacon.',table(['Constat','Interprétation'],[['Prises prolongées et besoin croissant.','Mécanisme iatrogène à rechercher.'],['Prurit et exposition concordante.','Allergie possiblement associée.'],['Obstruction fixe et asymétrique.','Cause structurelle ou focale à évaluer.'],['Symptômes systémiques après exposition.','Effet indésirable ou intoxication à prendre en charge.']])) ,
('Le {diagnostic est principalement clinique}. Il repose sur exposition compatible, évolution et exclusion raisonnée des autres causes. Aucun test biologique spécifique ne le confirme seul.',paras('La durée maximale de la notice sert au bon usage, pas à poser automatiquement le diagnostic au jour suivant. L’amélioration après arrêt soutient l’analyse, mais le suivi doit vérifier la maladie initiale et les autres mécanismes.')),
('Les {examens complémentaires ne sont pas systématiques}. Ils explorent une cause associée ou une présentation atypique. Un scanner n’est pas requis pour prouver une congestion rebond simple.',paras('Tests allergologiques, endoscopie ou imagerie sont choisis selon l’histoire et l’examen. Des symptômes cardiovasculaires ou neurologiques liés au produit nécessitent leur propre évaluation ; un bilan nasal seul serait insuffisant.')),
('L’{algorithme} commence par l’exposition et la sécurité. Il organise ensuite l’arrêt et le traitement de la cause initiale. Le suivi permet de distinguer rebond transitoire et obstacle persistant.',steps('Rechercher effet indésirable grave et signes d’une autre urgence.', 'Identifier exactement le vasoconstricteur et les habitudes de prise.', 'Organiser avec le professionnel un plan d’arrêt et des mesures de soutien adaptées.', 'Réévaluer tolérance, récupération et cause initiale ; adresser si l’obstruction persiste ou reste atypique.')),
('La {prise en charge vise la sortie de l’exposition causale}. Expliquer le rebond aide à éviter une nouvelle augmentation des doses. Le plan est individualisé selon tolérance et maladie associée.',paras('Une stratégie d’arrêt accompagnée est définie avec le professionnel. Aucun calendrier universel de diminution n’est inventé ; les modalités doivent permettre l’arrêt effectif sans simplement changer de marque.', '@@MEDICAMENTS@@', 'Les soins salins adaptés peuvent aider au confort. Un traitement anti-inflammatoire nasal peut être discuté selon la cause et son indication, mais une dose autorisée pour l’allergie n’est pas présentée comme une dose AIPS de sevrage. Les corticoïdes systémiques ne sont pas ajoutés automatiquement.')),
('La {prévention repose sur la durée et la compréhension du produit}. Donner une limite claire dès la première utilisation. Vérifier les concentrations et les restrictions d’âge évite d’autres accidents.',paras('Ne pas conserver un flacon comme traitement permanent d’une obstruction non explorée. Garder les produits hors de portée des enfants. En cas de grossesse ou d’allaitement, les restrictions de la spécialité restent applicables et ne sont pas annulées par l’usage antérieur.')),
('Le {point clé} est de reconnaître un traitement devenu facteur de persistance. Tous les sprays ne sont pas équivalents. L’arrêt du vasoconstricteur et la recherche de la cause initiale vont ensemble.',paras('La prise en charge soutient le patient et prévoit la réévaluation. Une obstruction persistante après arrêt ne doit pas être attribuée indéfiniment au rebond sans nouvel examen.'))
],[
('Quel type de spray est principalement concerné ?','Un vasoconstricteur nasal utilisé trop longtemps.'),
('Tous les sprays nasaux ont-ils le même risque de rebond ?','Non.'),
('Quel cycle entretient souvent l’usage ?','Soulagement bref, retour de congestion et répétition des prises.'),
('Faut-il connaître uniquement la marque ?','Non, principe actif, concentration, forme, fréquence et durée sont nécessaires.'),
('Quelle limite cite la notice Otrivin Rhume Classic ?','Ne pas utiliser pendant plus d’une semaine.'),
('Cette limite est-elle un critère diagnostique automatique ?','Non.'),
('Changer pour un autre vasoconstricteur résout-il forcément le problème ?','Non.'),
('La cause initiale peut-elle coexister avec le rebond ?','Oui, notamment allergie ou obstacle structurel.'),
('Existe-t-il un examen biologique spécifique de routine ?','Non.'),
('Un scanner est-il systématique ?','Non.'),
('Une céphalée soudaine sévère avec trouble visuel peut-elle être banalisée ?','Non, arrêter le produit et consulter immédiatement selon la notice.'),
('La dose allergique d’un corticoïde est-elle automatiquement une dose AIPS de sevrage ?','Non.'),
('Pourquoi prévoir un suivi ?','Pour accompagner l’arrêt et réévaluer une obstruction persistante.'),
('Quel ton employer avec le patient ?','Une explication claire et non culpabilisante du mécanisme et du plan.')
],(1,6,14),avertissement)
